    // -------------------------------------------------
    .reg .u32 %row, %col;
    mul.lo.u32 %row, %bid_y, 16;
    add.u32 %row, %row, %tid_y;
    mul.lo.u32 %col, %bid_x, 16;
    add.u32 %col, %col, %tid_x;

