    // Bounds check
    // -------------------------------------------------
    .reg .pred %p_row, %p_col;
    setp.ge.u32 %p_row, %row, %M;
    setp.ge.u32 %p_col, %col, %N;
    @%p_row bra END;
    @%p_col bra END;

    // -------------------------------------------------
    // Compute base pointer of A row (A is MxK, row‑major)
    // A_base = A + (row * K) * 2   // 2 bytes per half
    // -------------------------------------------------
    .reg .u64 %A_base, %tmp64;
    mul.wide.u32 %tmp64, %row, %K;          // row*K as 64‑bit
    shl.b64 %tmp64, %tmp64, 1;              // *2 bytes
    add.u64 %A_base, %A, %tmp64;            // A_base = A + row*K*2

    // -------------------------------------------------
    // Initialize accumulator (use fp32 for better precision)
    // -------------------------------------------------
    .reg .f32 %sum;
    mov.f32 %sum, 0f0;

